sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') return;

    var city = g_form.getValue('city');
    var state = g_form.getValue('state');
    var sysId = g_form.getUniqueValue();

    if (!city || !state) return;

    var ga = new GlideAjax('CheckDuplicateBase');
    ga.addParam('sysparm_name', 'checkDuplicateLocation');
    ga.addParam('sysparm_city', city);
    ga.addParam('sysparm_state', state);
    ga.addParam('sysparm_sys_id', sysId);

    ga.getXMLAnswer(function(response) {
        g_form.hideFieldMsg('city');
        g_form.hideFieldMsg('state');

        if (response === 'DUPLICATE_CITY_STATE') {
            g_form.setValue('city', '');
            g_form.setValue('state', '');
            g_form.showFieldMsg('city', 'A base with this city and state already exists.', 'error');
            g_form.showFieldMsg('state', 'A base with this city and state already exists.', 'error');
        }
    });
}
